def assert_row_types(self, sql, expected_types, row_index=0):
    result = self.query(sql)
    row = result.rows[row_index]
    self.assertEqual(len(row), len(expected_types))
    for position, (value, expected_type) in enumerate(
        zip(row, expected_types)
    ):
        self.assertIs(
            type(value),
            expected_type,
            msg="unexpected type in column %d of %r" % (position, sql),
        )

def assert_column_types(self, sql, expected_types):
    """Assert the value type of a single-column query, row by row."""
    result = self.query(sql)
    self.assertEqual(len(result.rows), len(expected_types))
    for index, (row, expected_type) in enumerate(
        zip(result.rows, expected_types)
    ):
        self.assertEqual(len(row), 1)
        self.assertIs(
            type(row[0]),
            expected_type,
            msg="unexpected type in row %d of %r" % (index, sql),
        )

